    h, w = len(grid), len(grid[0])
    a = [row[:] for row in grid]
    seeds = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
             if grid[r][c] not in (0, 1)]

    def one(r, c):
        return 0 <= r < h and 0 <= c < w and grid[r][c] != 0

    for sr, sc, color in seeds:
        # Find the largest solid 1-rectangle containing the marker.
        best = None
        for t in range(sr + 1):
            for b in range(sr, h):
                if any(not one(y, sc) for y in range(t, b + 1)):
                    continue
                left, right = 0, w - 1
                for y in range(t, b + 1):
                    x = sc
                    while x > 0 and one(y, x - 1):
                        x -= 1
                    left = max(left, x)
                    x = sc
                    while x + 1 < w and one(y, x + 1):
                        x += 1
                    right = min(right, x)
                rect = (t, b, left, right)
                area = (b - t + 1) * (right - left + 1)
                if best is None or area > best[0]:
                    best = (area, rect)

        if best is None:
            continue
        _, (t, b, l, r) = best
        hh, ww = b - t + 1, r - l + 1
        if hh < 3 or ww < 3:
            continue

        # Recolor the one-cell-inset core in matching solid rectangles.
        for y in range(h - hh + 1):
            for x in range(w - ww + 1):
                if all(grid[yy][xx] != 0
                       for yy in range(y, y + hh)
                       for xx in range(x, x + ww)):
                    for yy in range(y + 1, y + hh - 1):
                        for xx in range(x + 1, x + ww - 1):
                            if grid[yy][xx] == 1:
                                a[yy][xx] = color
    return a
