def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = [[False] * w for _ in range(h)]

    # Label 4-connected regions of non-background cells and associate each
    # region with any colored marker it contains.
    for sr in range(h):
        for sc in range(w):
            if grid[sr][sc] == 0 or seen[sr][sc]:
                continue
            stack = [(sr, sc)]
            seen[sr][sc] = True
            comp = []
            marker_colors = []
            while stack:
                r, c = stack.pop()
                comp.append((r, c))
                if grid[r][c] not in (0, 1):
                    marker_colors.append(grid[r][c])
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nr, nc = r + dr, c + dc
                    if (0 <= nr < h and 0 <= nc < w and
                            grid[nr][nc] != 0 and not seen[nr][nc]):
                        seen[nr][nc] = True
                        stack.append((nr, nc))

            if not marker_colors:
                continue
            color = marker_colors[0]
            for r, c in comp:
                if grid[r][c] != 1:
                    continue
                count = sum(
                    0 <= r + dr < h and 0 <= c + dc < w and
                    grid[r + dr][c + dc] != 0
                    for dr in (-1, 0, 1) for dc in (-1, 0, 1)
                )
                if count >= 7:
                    out[r][c] = color
    return out
